public class Lesson {
    public static void main(String[] args) {
        for (int i = 1; i <= 5; i++) {
            System.out.println("Torch #" + i + " placed.");
        }

        int count = 3;
        while (count > 0) {
            System.out.println("Countdown: " + count);
            count--;
        }
        System.out.println("Go!");
    }
}
